(675663, 70201, 15207, '<td valign="top">Wow! This one is really stunning. I LOVE the colours reflected on the lake. Superb composition. Good luck - 9</td>', 'Wow! This one is really stunning. I LOVE the colours reflected on the lake. Superb composition. Good luck - 9', '2004-04-19 14:30:16.000000', NULL, 1),
(675665, 70302, 15207, '<td valign="top">I''ve been stalking our local "heronry" every day for a month hoping to get a shot like this but I''ve had no luck! This is definitely the best one in this challenge. If you don''t win a ribbon I''ll fall of my chair. -10</td>', 'I''ve been stalking our local "heronry" every day for a month hoping to get a shot like this but I''ve had no luck! This is definitely the best one in this challenge. If you don''t win a ribbon I''ll fall of my chair. -10', '2004-04-19 14:31:13.000000', NULL, 1),
(675669, 70129, 19608, '<td valign="top">Very nice.  Mysterious,</td>', 'Very nice.  Mysterious,', '2004-04-19 14:33:14.000000', NULL, 1),
(675670, 70836, 19608, '<td valign="top">Sorry, but this image seems too busy - hard to read.</td>', 'Sorry, but this image seems too busy - hard to read.', '2004-04-19 14:34:03.000000', NULL, 1),
(675672, 69777, 19608, '<td valign="top">Sky is nice.  The bright reflection on the left edge of the fram draws the eye to that spot.  Not a great deal of interesting things to look at.</td>', 'Sky is nice.  The bright reflection on the left edge of the fram draws the eye to that spot.  Not a great deal of interesting things to look at.', '2004-04-19 14:35:30.000000', NULL, 1),
(675673, 70887, 19608, '<td valign="top">Colors work very well.</td>', 'Colors work very well.', '2004-04-19 14:35:55.000000', NULL, 1),
(675679, 70916, 19608, '<td valign="top">Way too much unused space that shows nothing - not effective as negative space.  Silhouette theme not really met in my view.</td>', 'Way too much unused space that shows nothing - not effective as negative space.  Silhouette theme not really met in my view.', '2004-04-19 14:37:18.000000', NULL, 1),
(675681, 70734, 2223, '<td valign="top">WOW</td>', 'WOW', '2004-04-19 14:39:13.000000', NULL, 1),
(675683, 70437, 19608, '<td valign="top">Rhe animal''s head is superb.  The merger of the treems with the back of the animal is unfortunate, it maye be effecrive to crop the image on a vertical line just behinf d the antlers - to the left of the tall pine.</td>', 'Rhe animal''s head is superb.  The merger of the treems with the back of the animal is unfortunate, it maye be effecrive to crop the image on a vertical line just behinf d the antlers - to the left of the tall pine.', '2004-04-19 14:39:16.000000', NULL, 1),
(675685, 70814, 19608, '<td valign="top">Nice shapes, pattern.  Trio of birds works well.</td>', 'Nice shapes, pattern.  Trio of birds works well.', '2004-04-19 14:39:49.000000', NULL, 1),
(675686, 70700, 19608, '<td valign="top">Perfect time of day with the hint of color in the sky.  Placement of the human figure is very effective.  The building on the right edge is a detractor because of the lighted windows.</td>', 'Perfect time of day with the hint of color in the sky.  Placement of the human figure is very effective.  The building on the right edge is a detractor because of the lighted windows.', '2004-04-19 14:41:07.000000', NULL, 1),
(675687, 70411, 19608, '<td valign="top">Sepia works well.  Pose of the model with rope/chain is great.</td>', 'Sepia works well.  Pose of the model with rope/chain is great.', '2004-04-19 14:41:55.000000', NULL, 1),
(675690, 70698, 19608, '<td valign="top">Good job of capturing the action.  The glow around the body doesn''t add anything for me - it seems too "uniform."  Image is pretty well centered which doesn''t add any impact.</td>', 'Good job of capturing the action.  The glow around the body doesn''t add anything for me - it seems too "uniform."  Image is pretty well centered which doesn''t add any impact.', '2004-04-19 14:43:27.000000', NULL, 1),
(675693, 70712, 19608, '<td valign="top">Great lighting.  Unfortunately, it''s not exactly what I''d call a silhouette.  Perhaps a bit too much dark area on the right side of the image.</td>', 'Great lighting.  Unfortunately, it''s not exactly what I''d call a silhouette.  Perhaps a bit too much dark area on the right side of the image.', '2004-04-19 14:45:14.000000', NULL, 1),
(675694, 70783, 19608, '<td valign="top">Nice shot - but where is the silhouette?</td>', 'Nice shot - but where is the silhouette?', '2004-04-19 14:45:48.000000', NULL, 1),
(675695, 70546, 19608, '<td valign="top">Great pose, but positioning a bit centered.  You can feel the "attitude" of the model.</td>', 'Great pose, but positioning a bit centered.  You can feel the "attitude" of the model.', '2004-04-19 14:46:48.000000', NULL, 1),
(675696, 70471, 19608, '<td valign="top">Colors are nice but the transition area a bit noisy.  Nice placement.</td>', 'Colors are nice but the transition area a bit noisy.  Nice placement.', '2004-04-19 14:47:49.000000', NULL, 1),
(675697, 70448, 19608, '<td valign="top">Nice colors but not really a silhouette.</td>', 'Nice colors but not really a silhouette.', '2004-04-19 14:48:23.000000', NULL, 1),
(675699, 70712, 18194, '<td valign="top">Interesting highlights but not really a Silhouette.</td>', 'Interesting highlights but not really a Silhouette.', '2004-04-19 14:49:30.000000', NULL, 1),
(675701, 70928, 19608, '<td valign="top">Great colors.  The fact that you can see the white (bluish) shoes adds a lot.  Without that, I''d say the bottom is too heavy, but with it - it works very well.  I don''t like the gray spot where you blocked out the sun in the tiny tree.  Much too obvious.  Don''t need the house/building on the left.</td>', 'Great colors.  The fact that you can see the white (bluish) shoes adds a lot.  Without that, I''d say the bottom is too heavy, but with it - it works very well.  I don''t like the gray spot where you blocked out the sun in the tiny tree.  Much too obvious.  Don''t need the house/building on the left.', '2004-04-19 14:51:06.000000', NULL, 1),
(675702, 70745, 18194, '<td valign="top">The clouds are overly blue to my taste.   It looks like the colors have been changed a large amount.</td>', 'The clouds are overly blue to my taste.   It looks like the colors have been changed a large amount.', '2004-04-19 14:51:07.000000', NULL, 1),
(675703, 70708, 18194, '<td valign="top">Very cute photo.</td>', 'Very cute photo.', '2004-04-19 14:51:48.000000', NULL, 1),
(675707, 70610, 18194, '<td valign="top">Way too much sharpening for my tastes.  Then the subject is very small.</td>', 'Way too much sharpening for my tastes.  Then the subject is very small.', '2004-04-19 14:53:06.000000', NULL, 1),
(675708, 70802, 19608, '<td valign="top">Colors are great.  The tilting image works in thiscase (normally I would NOT think so, but this one works - and works especially well with your title.)  I''d remove a bit at the bottom - and INCLUDE the top of the model''s head in the process.</td>', 'Colors are great.  The tilting image works in thiscase (normally I would NOT think so, but this one works - and works especially well with your title.)  I''d remove a bit at the bottom - and INCLUDE the top of the model''s head in the process.', '2004-04-19 14:53:11.000000', NULL, 1),
(675710, 70847, 18194, '<td valign="top">Not a bad photo but I found the tree in the background distracting.  It also looks like it might have been over sharpened just a bit.</td>', 'Not a bad photo but I found the tree in the background distracting.  It also looks like it might have been over sharpened just a bit.', '2004-04-19 14:54:35.000000', NULL, 1),
(675712, 70885, 19608, '<td valign="top">The layering effect is very nice.  The framing of your models under the tree limbs is great.  The rim lighting on the hair adds a nice touch.  It may look a bit better if some of the left edge were cropped off - so that the tree is on the left edsge.</td>', 'The layering effect is very nice.  The framing of your models under the tree limbs is great.  The rim lighting on the hair adds a nice touch.  It may look a bit better if some of the left edge were cropped off - so that the tree is on the left edsge.', '2004-04-19 14:55:12.000000', NULL, 1),
(675715, 70934, 19608, '<td valign="top">Nice color.  Contrail adds a lot.</td>', 'Nice color.  Contrail adds a lot.', '2004-04-19 14:55:40.000000', NULL, 1),
(675716, 70785, 19608, '<td valign="top">Good colors, nice texture in the shingles.  Not a very interesting subject.</td>', 'Good colors, nice texture in the shingles.  Not a very interesting subject.', '2004-04-19 14:56:24.000000', NULL, 1),
(675720, 70829, 18194, '<td valign="top">Over all I like the feel to this one but I have a hard time making out what I am looking at in terms of the people.  It looks like maybe parents with two children but one is sort of hidden.</td>', 'Over all I like the feel to this one but I have a hard time making out what I am looking at in terms of the people.  It looks like maybe parents with two children but one is sort of hidden.', '2004-04-19 14:57:07.000000', NULL, 1),
(675722, 70503, 19608, '<td valign="top">Stong image.  Nice colors.  Try cropping the top so that the upper balloon is just at the top (but not touching the edge.)</td>', 'Stong image.  Nice colors.  Try cropping the top so that the upper balloon is just at the top (but not touching the edge.)', '2004-04-19 14:57:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(675724, 70642, 18194, '<td valign="top">Great photo, I will be interested to hear where this was photographic at the end of the challenge..10</td>', 'Great photo, I will be interested to hear where this was photographic at the end of the challenge..10', '2004-04-19 14:58:24.000000', NULL, 1),
(675726, 70702, 19608, '<td valign="top">Cery nce colors and positioning oof the fisherman.  It would add a lot if you could see the fishing line</td>', 'Cery nce colors and positioning oof the fisherman.  It would add a lot if you could see the fishing line', '2004-04-19 14:58:56.000000', NULL, 1),
(675727, 70511, 16595, '<td valign="top">Very moody, nice colours and textures my favourite so far</td>', 'Very moody, nice colours and textures my favourite so far', '2004-04-19 14:59:27.000000', NULL, 1),
(675728, 70858, 19608, '<td valign="top">Nice curve of the landscape.  The wind blowing the hair is a great touch.</td>', 'Nice curve of the landscape.  The wind blowing the hair is a great touch.', '2004-04-19 14:59:58.000000', NULL, 1),
(675729, 70782, 18194, '<td valign="top">Nice photo but  not a silhouette.</td>', 'Nice photo but  not a silhouette.', '2004-04-19 15:00:20.000000', NULL, 1),
(675731, 70819, 19608, '<td valign="top">The colors really pop.  I don''t think the hand shape adds a thing and would like to take it out altogether.</td>', 'The colors really pop.  I don''t think the hand shape adds a thing and would like to take it out altogether.', '2004-04-19 15:00:56.000000', NULL, 1),
