(675778, 70671, 18194, '<td valign="top">Cute idea but the ant is out of focus.</td>', 'Cute idea but the ant is out of focus.', '2004-04-19 15:15:46.000000', NULL, 1),
(675779, 69939, 4008, '<td valign="top">I am wondeing whether it would have been a stronger image if you had singled out the two persons on the bench with just on or two trees around them. But good image anyway. Gorgeous colors and good framing.</td>', 'I am wondeing whether it would have been a stronger image if you had singled out the two persons on the bench with just on or two trees around them. But good image anyway. Gorgeous colors and good framing.', '2004-04-19 15:16:07.000000', NULL, 1),
(675780, 70265, 18194, '<td valign="top">This need much better focus</td>', 'This need much better focus', '2004-04-19 15:16:13.000000', NULL, 1),
(675783, 70732, 19608, '<td valign="top">Colors work very well.  Placement of the subject material dead center detracts.  Did you try this one on a diagonal line?</td>', 'Colors work very well.  Placement of the subject material dead center detracts.  Did you try this one on a diagonal line?', '2004-04-19 15:16:56.000000', NULL, 1),
(675784, 70252, 4008, '<td valign="top">Not sure wether the biker on the left adds anything. Or even the car. Just those two old trees would also have been strong. Great colors.</td>', 'Not sure wether the biker on the left adds anything. Or even the car. Just those two old trees would also have been strong. Great colors.', '2004-04-19 15:17:40.000000', NULL, 1),
(675786, 70600, 19608, '<td valign="top">Very graphic.  The smoke adds a great touch to an otherwise black /white rendition.</td>', 'Very graphic.  The smoke adds a great touch to an otherwise black /white rendition.', '2004-04-19 15:18:02.000000', NULL, 1),
(675787, 70945, 18194, '<td valign="top">The fact that the flower is lit from the front make this look very odd to me. That flower just looks out of place.</td>', 'The fact that the flower is lit from the front make this look very odd to me. That flower just looks out of place.', '2004-04-19 15:18:07.000000', NULL, 1),
(675788, 70840, 19608, '<td valign="top">Cute. Very graphic.</td>', 'Cute. Very graphic.', '2004-04-19 15:18:33.000000', NULL, 1),
(675789, 70803, 4008, '<td valign="top">Don''t see any silhouette.</td>', 'Don''t see any silhouette.', '2004-04-19 15:18:37.000000', NULL, 1),
(675792, 70708, 19608, '<td valign="top">Very nice composition, great title.  Sky works very well.</td>', 'Very nice composition, great title.  Sky works very well.', '2004-04-19 15:19:14.000000', NULL, 1),
(675793, 70945, 4008, '<td valign="top">The red flower spoils it in my opinion.</td>', 'The red flower spoils it in my opinion.', '2004-04-19 15:19:47.000000', NULL, 1),
(675794, 70566, 18194, '<td valign="top">Neat photo</td>', 'Neat photo', '2004-04-19 15:19:49.000000', NULL, 1),
(675797, 70239, 19608, '<td valign="top">Very nice composition.  Shadows at base add a lot.  I normally don''t like borders much, but this strong black one works well with your image.</td>', 'Very nice composition.  Shadows at base add a lot.  I normally don''t like borders much, but this strong black one works well with your image.', '2004-04-19 15:20:38.000000', NULL, 1),
(675799, 70536, 4008, '<td valign="top">Looks like a mammoth instead of an elephant. But good idea and great colors.</td>', 'Looks like a mammoth instead of an elephant. But good idea and great colors.', '2004-04-19 15:21:17.000000', NULL, 1),
(675801, 70684, 19608, '<td valign="top">Colrs REALLY pop! composition right on.  Maybe you could crop off a bit on the right side.</td>', 'Colrs REALLY pop! composition right on.  Maybe you could crop off a bit on the right side.', '2004-04-19 15:21:37.000000', NULL, 1),
(675803, 70646, 4008, '<td valign="top">Crop above the structure and you have a perfect image.</td>', 'Crop above the structure and you have a perfect image.', '2004-04-19 15:22:35.000000', NULL, 1),
(675804, 70252, 19608, '<td valign="top">Very graphic image with nice colors.  The bicylist is a bit close to the left side and I''d like to see a bit more space between the SUV and the tree behind it.</td>', 'Very graphic image with nice colors.  The bicylist is a bit close to the left side and I''d like to see a bit more space between the SUV and the tree behind it.', '2004-04-19 15:22:58.000000', NULL, 1),
(675806, 70701, 18194, '<td valign="top">Very dark and what can be made out is not focused.</td>', 'Very dark and what can be made out is not focused.', '2004-04-19 15:23:08.000000', NULL, 1),
(675807, 70892, 19608, '<td valign="top">Very busy</td>', 'Very busy', '2004-04-19 15:23:28.000000', NULL, 1),
(675808, 70570, 4008, '<td valign="top">Great colors, perfect framing/composition  and good silhouette.</td>', 'Great colors, perfect framing/composition  and good silhouette.', '2004-04-19 15:23:30.000000', NULL, 1),
(675812, 70322, 19608, '<td valign="top">Colors are nice.  Lighting on his back is very dramatic.</td>', 'Colors are nice.  Lighting on his back is very dramatic.', '2004-04-19 15:24:28.000000', NULL, 1),
(675813, 70746, 10785, '<td valign="top">This looks posterized.</td>', 'This looks posterized.', '2004-04-19 15:24:58.000000', NULL, 1),
