(675818, 70684, 18194, '<td valign="top">Nice photo.  I like the framing you did..8</td>', 'Nice photo.  I like the framing you did..8', '2004-04-19 15:27:11.000000', NULL, 1),
(675819, 70758, 4008, '<td valign="top">Is that a sky I am looking at ? What happened ? Looks strange.</td>', 'Is that a sky I am looking at ? What happened ? Looks strange.', '2004-04-19 15:27:37.000000', NULL, 1),
(675820, 70836, 18194, '<td valign="top">very dark</td>', 'very dark', '2004-04-19 15:27:41.000000', NULL, 1),
(675825, 70771, 18194, '<td valign="top">A very nice photo, it does have the appearance of being over sharpened however.</td>', 'A very nice photo, it does have the appearance of being over sharpened however.', '2004-04-19 15:29:34.000000', NULL, 1),
(675834, 70437, 4008, '<td valign="top">Too much going on in this picture.</td>', 'Too much going on in this picture.', '2004-04-19 15:32:33.000000', NULL, 1),
(675835, 70914, 18194, '<td valign="top">The perfect POV for this shot, very well done..9</td>', 'The perfect POV for this shot, very well done..9', '2004-04-19 15:33:11.000000', NULL, 1),
(675836, 70862, 4008, '<td valign="top">Bit busy in subject and composition, but  a great atmosphere.</td>', 'Bit busy in subject and composition, but  a great atmosphere.', '2004-04-19 15:33:14.000000', NULL, 1),
