(676088, 70537, 19608, '<td valign="top">Nice shapes and colors, very graphic.</td>', 'Nice shapes and colors, very graphic.', '2004-04-19 17:02:05.000000', NULL, 1),
(676091, 70669, 19608, '<td valign="top">Very graphic.  The bird adds a nice touch.  MOve the statue tio the right a bit so that its not so centered.  It would wok better if there were more space in front of the horse than behind it.</td>', 'Very graphic.  The bird adds a nice touch.  MOve the statue tio the right a bit so that its not so centered.  It would wok better if there were more space in front of the horse than behind it.', '2004-04-19 17:03:36.000000', NULL, 1),
