(676789, 70931, 16095, '<td valign="top">great capture-  looks like fun -  love the colors</td>', 'great capture-  looks like fun -  love the colors', '2004-04-20 01:30:50.000000', NULL, 1),
(676790, 70616, 16095, '<td valign="top">wonderful geometrical capture</td>', 'wonderful geometrical capture', '2004-04-20 01:31:17.000000', NULL, 1),
