(676800, 70911, 16520, '<td valign="top">I did something the same....Yours turned out very well I took about a 100 shots as the sun was setting...There is something about a tree in the sky that looks like it was etched with a lazer..... Great job</td>', 'I did something the same....Yours turned out very well I took about a 100 shots as the sun was setting...There is something about a tree in the sky that looks like it was etched with a lazer..... Great job', '2004-04-20 01:54:07.000000', NULL, 1),
(676801, 70298, 16520, '<td valign="top">Well done  I like the contrast and the detail.</td>', 'Well done  I like the contrast and the detail.', '2004-04-20 01:57:08.000000', NULL, 1),
(676802, 70779, 16520, '<td valign="top">I did kind of the same shot there is something about trees reaching into sky well done...</td>', 'I did kind of the same shot there is something about trees reaching into sky well done...', '2004-04-20 01:59:25.000000', NULL, 1),
(676804, 70800, 15495, '<td valign="top">Needs to be a little darker.</td>', 'Needs to be a little darker.', '2004-04-20 02:06:43.000000', NULL, 1),
