(676810, 70935, 15976, '<td valign="top">Best in class, picture is well done.</td>', 'Best in class, picture is well done.', '2004-04-20 02:10:16.000000', NULL, 1),
(676811, 70745, 15495, '<td valign="top">Cool Colors</td>', 'Cool Colors', '2004-04-20 02:10:27.000000', NULL, 1),
(676812, 70734, 15495, '<td valign="top">Very Nice</td>', 'Very Nice', '2004-04-20 02:10:38.000000', NULL, 1),
(676816, 70783, 3459, '<td valign="top">Great image, but not a silhouette, 5.</td>', 'Great image, but not a silhouette, 5.', '2004-04-20 02:32:40.000000', NULL, 1),
(676817, 69939, 11813, '<td valign="top">Very nice capture. I would Definately have cropped out the telephone pole on the left side... it takes away (just a tad) from the natural look of the scene.</td>', 'Very nice capture. I would Definately have cropped out the telephone pole on the left side... it takes away (just a tad) from the natural look of the scene.', '2004-04-20 02:35:06.000000', NULL, 1),
(676818, 70953, 11813, '<td valign="top">Nicely done. I would have prefered both shot fronts to be completely in view but, it doesn''t detract from the image that much for me. I like this nonetheless</td>', 'Nicely done. I would have prefered both shot fronts to be completely in view but, it doesn''t detract from the image that much for me. I like this nonetheless', '2004-04-20 02:36:58.000000', NULL, 1),
(676819, 70749, 11813, '<td valign="top">YOu had a nice idea here but, the horizontal plane is off in a way that is not sitting right with me visually. Just a slight rotation to the left would have easily cureed this. Nevertheless, it''s a nice silhouette shot and, that''s what we are here for :-)</td>', 'YOu had a nice idea here but, the horizontal plane is off in a way that is not sitting right with me visually. Just a slight rotation to the left would have easily cureed this. Nevertheless, it''s a nice silhouette shot and, that''s what we are here for :-)', '2004-04-20 02:40:53.000000', NULL, 1),
(676821, 70803, 20324, '<td valign="top">Silhouettes???</td>', 'Silhouettes???', '2004-04-20 02:42:10.000000', NULL, 1),
(676822, 70434, 11813, '<td valign="top">YOu did a nice job with this shot. I know it''s personal preference but, I would prefer not seeing the top right corner light distraction. Other would say it forms the head visually so, it''s just my nit. Nice work.</td>', 'YOu did a nice job with this shot. I know it''s personal preference but, I would prefer not seeing the top right corner light distraction. Other would say it forms the head visually so, it''s just my nit. Nice work.', '2004-04-20 02:43:05.000000', NULL, 1),
(676823, 70265, 20324, '<td valign="top">Out of focus, what did you want to "say" with this pictures? Doesn''t "touch" me</td>', 'Out of focus, what did you want to "say" with this pictures? Doesn''t "touch" me', '2004-04-20 02:48:14.000000', NULL, 1),
(676825, 70573, 11813, '<td valign="top">A great idea and a nice composition. The background for some reason seems a little unatural to me. I like your visual perspective.</td>', 'A great idea and a nice composition. The background for some reason seems a little unatural to me. I like your visual perspective.', '2004-04-20 02:50:36.000000', NULL, 1),
(676827, 70298, 11813, '<td valign="top">This is one of my favorites in the challenge. Nicely done. Might have been even more interesting of you could have formed a half moon (complete 180 degree) view of the dandelion.... note to self :-)</td>', 'This is one of my favorites in the challenge. Nicely done. Might have been even more interesting of you could have formed a half moon (complete 180 degree) view of the dandelion.... note to self :-)', '2004-04-20 02:52:47.000000', NULL, 1),
(676828, 70802, 20324, '<td valign="top">Sorry, I don''t like the composition. Did you crop it, if yes I would do it diffrent way.</td>', 'Sorry, I don''t like the composition. Did you crop it, if yes I would do it diffrent way.', '2004-04-20 02:53:21.000000', NULL, 1),
(676833, 70307, 11813, '<td valign="top">very nice capture, nice composition, nice natural lighting. A change of positiojn / perspective might have caught more actual silhouete than you are displaying here but, I stil think this is a beautiful image.</td>', 'very nice capture, nice composition, nice natural lighting. A change of positiojn / perspective might have caught more actual silhouete than you are displaying here but, I stil think this is a beautiful image.', '2004-04-20 02:59:17.000000', NULL, 1),
(676834, 70935, 19263, '<td valign="top">Awsome! What a great model!</td>', 'Awsome! What a great model!', '2004-04-20 03:00:53.000000', NULL, 1),
(676835, 70252, 11813, '<td valign="top">nice natural color sky, without al the UNatural oversaturated colors you see in other sky / silhouette images ( I know how tempting it is to do). Just my opinion but, the tree on the left has MUCH more visual appeal than anything in this image. I would have focused my attention (no pun) on that alone in the image against the sky. Anyway, nice capture</td>', 'nice natural color sky, without al the UNatural oversaturated colors you see in other sky / silhouette images ( I know how tempting it is to do). Just my opinion but, the tree on the left has MUCH more visual appeal than anything in this image. I would have focused my attention (no pun) on that alone in the image against the sky. Anyway, nice capture', '2004-04-20 03:02:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(676836, 70642, 11813, '<td valign="top">Even though the elements do not appear in as sharp focus as I would like to see, your image is very well composed, has natural silhouettes, a subdued and interesting background and nice relfections.</td>', 'Even though the elements do not appear in as sharp focus as I would like to see, your image is very well composed, has natural silhouettes, a subdued and interesting background and nice relfections.', '2004-04-20 03:04:13.000000', NULL, 1),
(676838, 70935, 11813, '<td valign="top">It''s a beautiful silhouette. I only wish the background were a bit more evenly distributed but, maybe that''s just a personal preference for me? Your composition is great.</td>', 'It''s a beautiful silhouette. I only wish the background were a bit more evenly distributed but, maybe that''s just a personal preference for me? Your composition is great.', '2004-04-20 03:06:46.000000', NULL, 1),
(676841, 70627, 11813, '<td valign="top">you have / had a great idea here. I''m personally not fond of center subject compositions, which takes away from the image visually.... for me.</td>', 'you have / had a great idea here. I''m personally not fond of center subject compositions, which takes away from the image visually.... for me.', '2004-04-20 03:08:52.000000', NULL, 1),
(676842, 70295, 11813, '<td valign="top">Nice silhouette, nice composition, nice timing. Image appears a bit unsharp but, that may be due to overcompression of your image?</td>', 'Nice silhouette, nice composition, nice timing. Image appears a bit unsharp but, that may be due to overcompression of your image?', '2004-04-20 03:10:12.000000', NULL, 1),
(676844, 70570, 11813, '<td valign="top">I like the image, I like the silhouette and, light houses are popular subjects for silhouettes, so you have a good subject of interest. The only thing I do NOT like, is the composition which for me, is just too visually tight a composition. Also, i have not yet figured out why but, my mind keeps wanting to see the lighthouse on the left side of the image, but that''s only a horizontal rotation away :-)</td>', 'I like the image, I like the silhouette and, light houses are popular subjects for silhouettes, so you have a good subject of interest. The only thing I do NOT like, is the composition which for me, is just too visually tight a composition. Also, i have not yet figured out why but, my mind keeps wanting to see the lighthouse on the left side of the image, but that''s only a horizontal rotation away :-)', '2004-04-20 03:14:56.000000', NULL, 1),
(676845, 70900, 11813, '<td valign="top">Nice natural sky colors (thank you for not OVERsaturating the colors as others seem to enjoy doing :-)</td>', 'Nice natural sky colors (thank you for not OVERsaturating the colors as others seem to enjoy doing :-)', '2004-04-20 03:15:59.000000', NULL, 1),
(676846, 70917, 11813, '<td valign="top">nice subject for silhouettes. A change in position / perspective could improve on your shot. The eye flows around from tree top to tree top and, that''s a "good thing"</td>', 'nice subject for silhouettes. A change in position / perspective could improve on your shot. The eye flows around from tree top to tree top and, that''s a "good thing"', '2004-04-20 03:18:54.000000', NULL, 1),
(676847, 70840, 11813, '<td valign="top">You have a really great idea here. I like the interaction between the subjects. For some reason though, there''s something missing from the image that I can''t quite put my finger on yet.</td>', 'You have a really great idea here. I like the interaction between the subjects. For some reason though, there''s something missing from the image that I can''t quite put my finger on yet.', '2004-04-20 03:21:31.000000', NULL, 1),
(676848, 70448, 11813, '<td valign="top">I like this iamge more than most of the others in this challenge. What I like is the perspective, the lighting on the drun and symbols and the natural silhouette agains the backlighting.. and the expression on the drummer. Oh, and the composition :-)<br/>Nice work</td>', 'I like this iamge more than most of the others in this challenge. What I like is the perspective, the lighting on the drun and symbols and the natural silhouette agains the backlighting.. and the expression on the drummer. Oh, and the composition :-)Nice work', '2004-04-20 03:23:47.000000', NULL, 1),
(676851, 70302, 11813, '<td valign="top">NIce capture and good timing on your part. The image in my honest opinion is greatly over saturated / contrasted but, some people seem to like this "look" in images.</td>', 'NIce capture and good timing on your part. The image in my honest opinion is greatly over saturated / contrasted but, some people seem to like this "look" in images.', '2004-04-20 03:25:18.000000', NULL, 1),
(676853, 70710, 11813, '<td valign="top">Nice capture and nice timing. That one cloud formation to the right of the sun (the darker formation) for some reason looks unatural in the scene... no fault of yours ofcourse.  The waves are engaging</td>', 'Nice capture and nice timing. That one cloud formation to the right of the sun (the darker formation) for some reason looks unatural in the scene... no fault of yours ofcourse.  The waves are engaging', '2004-04-20 03:26:35.000000', NULL, 1),
(676857, 70858, 18838, '<td valign="top">the sky looks a bit manipulated ... like it a lot though</td>', 'the sky looks a bit manipulated ... like it a lot though', '2004-04-20 03:32:17.000000', NULL, 1),
(676860, 70725, 18838, '<td valign="top">nice dramatic light</td>', 'nice dramatic light', '2004-04-20 03:34:55.000000', NULL, 1),
(676861, 70892, 11813, '<td valign="top">nice composition / crop but where are the babies? :-)</td>', 'nice composition / crop but where are the babies? :-)', '2004-04-20 03:35:40.000000', NULL, 1),
(676863, 70935, 18838, '<td valign="top">excellent light ... my favorite</td>', 'excellent light ... my favorite', '2004-04-20 03:36:22.000000', NULL, 1),
(676864, 70889, 11813, '<td valign="top">Very interesting. Nice composition</td>', 'Very interesting. Nice composition', '2004-04-20 03:36:47.000000', NULL, 1),
