(678781, 70885, 18722, '<td valign="top">Very interesting color for the sky.</td>', 'Very interesting color for the sky.', '2004-04-21 05:10:29.000000', NULL, 1),
(678784, 70911, 18722, '<td valign="top">Fantastic view.  I would not have included the vertical cloud (contrail?) on the left, it makes a much more stiking scene without it.</td>', 'Fantastic view.  I would not have included the vertical cloud (contrail?) on the left, it makes a much more stiking scene without it.', '2004-04-21 05:13:15.000000', NULL, 1),
