(680422, 70448, 2158, '<td valign="top">Nice shot, but it''s not a silhouette.</td>', 'Nice shot, but it''s not a silhouette.', '2004-04-21 22:16:40.000000', NULL, 1),
(680427, 70626, 16151, '<td valign="top">Good photo.</td>', 'Good photo.', '2004-04-21 22:18:03.000000', NULL, 1),
(680429, 70719, 16151, '<td valign="top">Pretty nice shot.</td>', 'Pretty nice shot.', '2004-04-21 22:18:23.000000', NULL, 1),
