(682024, 70642, 20608, '<td valign="top">................... Wow .................. there is no other words</td>', '................... Wow .................. there is no other words', '2004-04-22 23:37:29.000000', NULL, 1),
(682025, 70642, 9964, '<td valign="top">wow, beautiful</td>', 'wow, beautiful', '2004-04-22 23:38:29.000000', NULL, 1),
(682036, 70732, 19966, '<td valign="top">Eeeuuuuu. Really good shot, but yuck. (9)</td>', 'Eeeuuuuu. Really good shot, but yuck. (9)', '2004-04-22 23:45:34.000000', NULL, 1),
(682078, 70808, 18505, '<td valign="top">Beautiful, dramatic image.  I like the treed in the window.  The blue sky and fluffy clouds add as well.  I bet this site is also gorgeous with a dramatic sunrise/sunset.  You get a 10!</td>', 'Beautiful, dramatic image.  I like the treed in the window.  The blue sky and fluffy clouds add as well.  I bet this site is also gorgeous with a dramatic sunrise/sunset.  You get a 10!', '2004-04-23 00:18:22.000000', NULL, 1),
(682110, 70937, 10818, '<td valign="top">Thats very pretty, wonderful shot.</td>', 'Thats very pretty, wonderful shot.', '2004-04-23 00:55:13.000000', NULL, 1),
(682124, 70935, 16703, '<td valign="top">dr jones???? dr jones??? is that you???</td>', 'dr jones???? dr jones??? is that you???', '2004-04-23 01:18:05.000000', NULL, 1),
(682177, 70912, 18552, '<td valign="top">Very elegant and beautiful silhouette. Can''t think of anything you could have done better - it''s just right the way it is.</td>', 'Very elegant and beautiful silhouette. Can''t think of anything you could have done better - it''s just right the way it is.', '2004-04-23 02:16:37.000000', NULL, 1),
(682180, 70945, 18552, '<td valign="top">Interesting picture. The girls are almost in full silhouette but I''m not sure of the purpose of the big flower in the front of the picture. It become the main subject instead of the girls.</td>', 'Interesting picture. The girls are almost in full silhouette but I''m not sure of the purpose of the big flower in the front of the picture. It become the main subject instead of the girls.', '2004-04-23 02:18:11.000000', NULL, 1),
(682181, 70846, 18552, '<td valign="top">Really an enjoyable picture to look at. However, it isn''t really a silhouette. The tractors are against the skyline but they aren''t in silhouette. I really like the sky.</td>', 'Really an enjoyable picture to look at. However, it isn''t really a silhouette. The tractors are against the skyline but they aren''t in silhouette. I really like the sky.', '2004-04-23 02:19:46.000000', NULL, 1),
(682183, 70701, 18552, '<td valign="top">The trees form a pleasant silhouette against the sky. The sky is a bit dark though to really show them as best they could be.</td>', 'The trees form a pleasant silhouette against the sky. The sky is a bit dark though to really show them as best they could be.', '2004-04-23 02:22:42.000000', NULL, 1),
(682185, 70803, 18552, '<td valign="top">Very nice clear, well taken picture. However, it isn''t a silhouette.</td>', 'Very nice clear, well taken picture. However, it isn''t a silhouette.', '2004-04-23 02:23:26.000000', NULL, 1),
(682186, 70783, 18552, '<td valign="top">Very nice duck picture; however, it isn''t a silhouette.</td>', 'Very nice duck picture; however, it isn''t a silhouette.', '2004-04-23 02:24:06.000000', NULL, 1),
(682187, 70904, 18552, '<td valign="top">This really isn''t a silhouette. It is an interesting picture.</td>', 'This really isn''t a silhouette. It is an interesting picture.', '2004-04-23 02:25:41.000000', NULL, 1),
(682188, 70749, 18552, '<td valign="top">Wonderfully clear and well focused picture of wine glasses. However, it isn''t a silhouette.</td>', 'Wonderfully clear and well focused picture of wine glasses. However, it isn''t a silhouette.', '2004-04-23 02:26:26.000000', NULL, 1),
(682189, 70206, 18552, '<td valign="top">Lovely sunset silhouette,</td>', 'Lovely sunset silhouette,', '2004-04-23 02:28:06.000000', NULL, 1),
(682190, 70960, 18552, '<td valign="top">Very nice tree silhouette. The picture looks a bit crowded, some more empty space would have been nice.</td>', 'Very nice tree silhouette. The picture looks a bit crowded, some more empty space would have been nice.', '2004-04-23 02:29:49.000000', NULL, 1),
(682191, 70914, 18552, '<td valign="top">Excellent silhouette picture. It''s very unique in that the sky isn''t providing the backlighting. Very creative and interesting shot!</td>', 'Excellent silhouette picture. It''s very unique in that the sky isn''t providing the backlighting. Very creative and interesting shot!', '2004-04-23 02:31:00.000000', NULL, 1),
(682197, 70201, 5318, '<td valign="top">awsome pic  honey! I would love to get this one our wall.</td>', 'awsome pic  honey! I would love to get this one our wall.', '2004-04-23 02:44:12.000000', NULL, 1),
(682236, 70734, 11078, '<td valign="top">very good silhouette  love the colours and detail</td>', 'very good silhouette  love the colours and detail', '2004-04-23 03:53:30.000000', NULL, 1),
(682238, 70724, 11078, '<td valign="top">This has a very different effect almost like an oil painting <br/>I see this as a shadow not a silhouette I like it though its just very unusual</td>', 'This has a very different effect almost like an oil painting I see this as a shadow not a silhouette I like it though its just very unusual', '2004-04-23 03:55:16.000000', NULL, 1),
(682240, 70570, 11078, '<td valign="top">very nice</td>', 'very nice', '2004-04-23 03:57:41.000000', NULL, 1),
(682243, 70899, 6388, '<td valign="top">superb. i love this.  I''m sure the anal-ysts will knock you for the reflections on the cat, but who cares?  still a silhouette, and still a fabulous shot.  I might burn the highlights a little (just the blown our reflections on the cat, plus whatever is over the horse''s head).  very well done.</td>', 'superb. i love this.  I''m sure the anal-ysts will knock you for the reflections on the cat, but who cares?  still a silhouette, and still a fabulous shot.  I might burn the highlights a little (just the blown our reflections on the cat, plus whatever is over the horse''s head).  very well done.', '2004-04-23 04:07:52.000000', NULL, 1),
(682244, 70840, 6388, '<td valign="top">I''m going to go out on a limb and call this a top 10 shot.  great idea, and it''s executed well.  a little forced, but still a great idea.  <br/>P</td>', 'I''m going to go out on a limb and call this a top 10 shot.  great idea, and it''s executed well.  a little forced, but still a great idea.  P', '2004-04-23 04:11:18.000000', NULL, 1),
(682250, 70681, 6388, '<td valign="top">I''d level the horizon a little (i know others hve probably said it already, but they''re right) and maybe play with the levels a little to enhance the silhouettes.  i love the haze, and the colours are very nice.  border is a little on the intrusive side.<br/>good luck,<br/>Pedro</td>', 'I''d level the horizon a little (i know others hve probably said it already, but they''re right) and maybe play with the levels a little to enhance the silhouettes.  i love the haze, and the colours are very nice.  border is a little on the intrusive side.good luck,Pedro', '2004-04-23 04:25:16.000000', NULL, 1),
(682254, 70671, 6388, '<td valign="top">the shallow depth doesn''t help here. i like the idea, and the angle in nice...it leads through the frame well.  smaller aperture would add depth, and darker the silhoueete a little too. :)<br/>P</td>', 'the shallow depth doesn''t help here. i like the idea, and the angle in nice...it leads through the frame well.  smaller aperture would add depth, and darker the silhoueete a little too. :)P', '2004-04-23 04:29:04.000000', NULL, 1),
(682288, 70511, 11078, '<td valign="top">Nice colours in this image and very dramatic sky <br/>Nice image</td>', 'Nice colours in this image and very dramatic sky Nice image', '2004-04-23 06:01:32.000000', NULL, 1),
(682291, 70684, 11078, '<td valign="top">beautiful sky nice detail and great silhouette</td>', 'beautiful sky nice detail and great silhouette', '2004-04-23 06:04:25.000000', NULL, 1),
(682294, 70667, 11078, '<td valign="top">very nice well done</td>', 'very nice well done', '2004-04-23 06:07:36.000000', NULL, 1),
