INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(682333, 70734, 15407, '<td valign="top">What happened to the landing gear on the left?</td>', 'What happened to the landing gear on the left?', '2004-04-23 08:18:35.000000', NULL, 1),
(682350, 70940, 2764, '<td valign="top">, maybe the red world is friendly.<br/>awck - my comment disappeared - it was rather long, I will recreat it later</td>', ', maybe the red world is friendly.awck - my comment disappeared - it was rather long, I will recreat it later', '2004-04-23 08:54:39.000000', NULL, 1),
(682365, 70724, 11678, '<td valign="top">You''ll catch grief from the "purists" but I just love this. Hardly anyone here will jump out with an abstract. I think this is very well done. The only thing that dropped my vote from a 10 were the few artifacts that are mostly white-ish on the pups back. And one rather bright artifact on the shadow at about the left ear.  I know I''m being an extreme critic, here, but why not... I feel this is sellable work. This image REALLY works for me. Heck, I changed it to a 10... just can''t help myself. Do be aware of removing or softening those few bright artifacts, though. I hope your RAW image has enough pixels to take this to 8x10 prints.... it''s awesome.</td>', 'You''ll catch grief from the "purists" but I just love this. Hardly anyone here will jump out with an abstract. I think this is very well done. The only thing that dropped my vote from a 10 were the few artifacts that are mostly white-ish on the pups back. And one rather bright artifact on the shadow at about the left ear.  I know I''m being an extreme critic, here, but why not... I feel this is sellable work. This image REALLY works for me. Heck, I changed it to a 10... just can''t help myself. Do be aware of removing or softening those few bright artifacts, though. I hope your RAW image has enough pixels to take this to 8x10 prints.... it''s awesome.', '2004-04-23 09:24:34.000000', NULL, 1),
(682366, 70935, 11678, '<td valign="top">Normally I think that nudes are passe, but when I see a really good one, I score it appropriately.. 10.<br/></td>', 'Normally I think that nudes are passe, but when I see a really good one, I score it appropriately.. 10.', '2004-04-23 09:25:42.000000', NULL, 1),
(682404, 70637, 11895, '<td valign="top">I like the rose but the background, or lack thereof, is a detraction</td>', 'I like the rose but the background, or lack thereof, is a detraction', '2004-04-23 10:37:42.000000', NULL, 1),
(682406, 70758, 16862, '<td valign="top">This is a photoshop filter all the way through</td>', 'This is a photoshop filter all the way through', '2004-04-23 10:40:52.000000', NULL, 1),
(682407, 70958, 16862, '<td valign="top">A good idea, but out of focus</td>', 'A good idea, but out of focus', '2004-04-23 10:41:43.000000', NULL, 1),
(682428, 70669, 20577, '<td valign="top">Photo is awesome! Love the cloud in the background. The only thing I don''t care for is the bird, but it doesn''t really matter because this picture is great!</td>', 'Photo is awesome! Love the cloud in the background. The only thing I don''t care for is the bird, but it doesn''t really matter because this picture is great!', '2004-04-23 10:56:49.000000', NULL, 1),
(682434, 70783, 20577, '<td valign="top">Good picture, but where is the silhouette?</td>', 'Good picture, but where is the silhouette?', '2004-04-23 11:01:11.000000', NULL, 1),
(682511, 70846, 11895, '<td valign="top">I really like this pic, the clouds look great, but I don''t feel it meets the challenge very well, the tractors are such a small part of the image, and the light color in their rear wheels makes me wonder if they are really backlit silhouettes; bottom should be cropped up some to get rid of the distraction in the lower right corner</td>', 'I really like this pic, the clouds look great, but I don''t feel it meets the challenge very well, the tractors are such a small part of the image, and the light color in their rear wheels makes me wonder if they are really backlit silhouettes; bottom should be cropped up some to get rid of the distraction in the lower right corner', '2004-04-23 12:40:17.000000', NULL, 1),
(682514, 69943, 11895, '<td valign="top">I really like this pic but don''t feel it meets the challenge well, the horses appear to be sidelit rather than backlit silhouettes, raised a point on second viewing</td>', 'I really like this pic but don''t feel it meets the challenge well, the horses appear to be sidelit rather than backlit silhouettes, raised a point on second viewing', '2004-04-23 12:44:06.000000', NULL, 1),
(682516, 70642, 11895, '<td valign="top">looks a bit over-processed</td>', 'looks a bit over-processed', '2004-04-23 12:45:41.000000', NULL, 1),
(682523, 70829, 11895, '<td valign="top">I wish the blue light came all the way out to the foreground at the top and left of the image, it seems unatural as it is, otherwise a very good pic that meets the challenge well, after the challenge I''d like to know how this was processed</td>', 'I wish the blue light came all the way out to the foreground at the top and left of the image, it seems unatural as it is, otherwise a very good pic that meets the challenge well, after the challenge I''d like to know how this was processed', '2004-04-23 12:54:45.000000', NULL, 1),
(682530, 70724, 11895, '<td valign="top">not a true backlit silhouette, but a pleasing image nonetheless</td>', 'not a true backlit silhouette, but a pleasing image nonetheless', '2004-04-23 12:59:40.000000', NULL, 1),
(682531, 70935, 11895, '<td valign="top">meets the challenge but not very imaginative</td>', 'meets the challenge but not very imaginative', '2004-04-23 13:01:05.000000', NULL, 1),
(682550, 70698, 16004, '<td valign="top">Great timing and a splendid capture - very sharp for an action shot - but I think you''ve slightly overdone the post processing.  You could do with a little less of the unsharp mask (i''m guessing that''s what brought about the halo effect) and the desaturating has somehow dulled the impact - was it really worse in colour?  Also, the sky is a bit on the noisy / pixelated side, and a gentle neatimage / guasian blur on the background might have reduced this a bit.  The hand on the left is also a bit disturbing as it looks like a monster has bitten two of the fingers off - but that''s just an observation and not a score altering thing...  good effort, you just need to tone down your editting a bit.</td>', 'Great timing and a splendid capture - very sharp for an action shot - but I think you''ve slightly overdone the post processing.  You could do with a little less of the unsharp mask (i''m guessing that''s what brought about the halo effect) and the desaturating has somehow dulled the impact - was it really worse in colour?  Also, the sky is a bit on the noisy / pixelated side, and a gentle neatimage / guasian blur on the background might have reduced this a bit.  The hand on the left is also a bit disturbing as it looks like a monster has bitten two of the fingers off - but that''s just an observation and not a score altering thing...  good effort, you just need to tone down your editting a bit.', '2004-04-23 13:17:19.000000', NULL, 1),
(682555, 70568, 16004, '<td valign="top">I think this is a true silhouette - well, I think it definitely fit''s the challenge.  Quite a beautiful and arresting shot - though i''m impressed that the bride allowed you to muck about getting arty farty shots (though it would make a lovely momento of the day - and i assume it was The Day for real, right?).  Lighting is wonderfully great.  The background is a little bit cluttered for my personal taste (perhaps it might work if the background was subtley blurred a little more?) but i still want to give this a 10 because it''s just so good!  well done you!</td>', 'I think this is a true silhouette - well, I think it definitely fit''s the challenge.  Quite a beautiful and arresting shot - though i''m impressed that the bride allowed you to muck about getting arty farty shots (though it would make a lovely momento of the day - and i assume it was The Day for real, right?).  Lighting is wonderfully great.  The background is a little bit cluttered for my personal taste (perhaps it might work if the background was subtley blurred a little more?) but i still want to give this a 10 because it''s just so good!  well done you!', '2004-04-23 13:22:17.000000', NULL, 1),
(682583, 70568, 11895, '<td valign="top">good use of B&amp;W</td>', 'good use of B&W', '2004-04-23 13:48:57.000000', NULL, 1),
