(684200, 70746, 14614, '<td valign="top">This is lovely -- your post-shot processing adds to the feel.  One of my favorites this challenge</td>', 'This is lovely -- your post-shot processing adds to the feel.  One of my favorites this challenge', '2004-04-25 08:49:22.000000', NULL, 1),
(684202, 70411, 14614, '<td valign="top">You''ve told a great story here... use of sepia, position of the subjects is great.  One of my ribbon picks this challenge.</td>', 'You''ve told a great story here... use of sepia, position of the subjects is great.  One of my ribbon picks this challenge.', '2004-04-25 08:50:24.000000', NULL, 1),
(684203, 70911, 14614, '<td valign="top">you''ve set a serene mood with your use of light and color.  the trees in the distance create a lot of interest and perspective.  One of my ribbon picks this challenge</td>', 'you''ve set a serene mood with your use of light and color.  the trees in the distance create a lot of interest and perspective.  One of my ribbon picks this challenge', '2004-04-25 08:51:42.000000', NULL, 1),
(684206, 70570, 14614, '<td valign="top">Just lovely -- your sky has wonderful colors -- I''d like to see even more spaces for it to show through in the bottome of the shot.  as presented -- one of my favorites in the challenge</td>', 'Just lovely -- your sky has wonderful colors -- I''d like to see even more spaces for it to show through in the bottome of the shot.  as presented -- one of my favorites in the challenge', '2004-04-25 08:53:25.000000', NULL, 1),
(684207, 70129, 14614, '<td valign="top">beautifully done... I think I''d like to see a smidge more color in the ground.  as presented -- one of my favorites this challenge</td>', 'beautifully done... I think I''d like to see a smidge more color in the ground.  as presented -- one of my favorites this challenge', '2004-04-25 08:54:26.000000', NULL, 1),
(684208, 70642, 14614, '<td valign="top">wonderfully moody - like how you used the fog to create the silhoette.  great detail in the water.  second pass has me up this to one of my ribbon picks</td>', 'wonderfully moody - like how you used the fog to create the silhoette.  great detail in the water.  second pass has me up this to one of my ribbon picks', '2004-04-25 08:54:58.000000', NULL, 1),
