(684210, 70298, 14614, '<td valign="top">a macro silhouette -- well done.  the blue tint is a nice choice.  one of my favorites this challenge</td>', 'a macro silhouette -- well done.  the blue tint is a nice choice.  one of my favorites this challenge', '2004-04-25 08:57:36.000000', NULL, 1),
