INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(692650, 70481, 17851, '<td valign="top">i really liked this one ..should have done better</td>', 'i really liked this one ..should have done better', '2004-05-01 11:55:20.000000', NULL, 0),
(692741, 70699, 1031, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by beckettboots:</b></div><hr/><i>My Opinion: As a pure work of photographic art, I think the shot could benefit from color. I''m a sucker for cloudscapes and majestic skies. I might like to see it recropped in color to highlight the feeling of the ship at sea corner of the building part.</i></td></tr></table> <br/>Thanks for the review! I agree with about all of it, and considered color versions as you  can see below. I''m a sucker for cloudscapes too, and one reason I went B+W was to put more emphasis on the silhouette aspect rather than make it a nice cloudscape with an antenna in the way.<br/> <br/>I''m not sure why it was so grainy; I was in shadow at the time while it was pretty bright around the subject area, so maybe that affected the exposure or focus.<br/> <br/>I wish I had thought of the ship metaphor -- perhaps titling it <b>Bowsprit</b> could have bumped it up a tenth ...<br/> <br/>Original: <a href="//www.pbase.com/image/28467639" rel="nofollow" target="_blank"><img alt="'' . substr(''//www.pbase.com/image/28467639/small.jpg'', strrpos(''//www.pbase.com/image/28467639/small.jpg'', ''/'') + 1) . ''" border="0" src="//www.pbase.com/image/28467639/small.jpg"/></a> <br/>Adjusted: <a href="//www.pbase.com/image/28467640" rel="nofollow" target="_blank"><img alt="'' . substr(''//www.pbase.com/image/28467640/small.jpg'', strrpos(''//www.pbase.com/image/28467640/small.jpg'', ''/'') + 1) . ''" border="0" src="//www.pbase.com/image/28467640/small.jpg"/></a> <br/>"Colorized": <a href="//www.pbase.com/image/28467642" rel="nofollow" target="_blank"><img alt="'' . substr(''//www.pbase.com/image/28467642/small.jpg'', strrpos(''//www.pbase.com/image/28467642/small.jpg'', ''/'') + 1) . ''" border="0" src="//www.pbase.com/image/28467642/small.jpg"/></a></td>', 'Originally posted by beckettboots:My Opinion: As a pure work of photographic art, I think the shot could benefit from color. I''m a sucker for cloudscapes and majestic skies. I might like to see it recropped in color to highlight the feeling of the ship at sea corner of the building part. Thanks for the review! I agree with about all of it, and considered color versions as you  can see below. I''m a sucker for cloudscapes too, and one reason I went B+W was to put more emphasis on the silhouette aspect rather than make it a nice cloudscape with an antenna in the way. I''m not sure why it was so grainy; I was in shadow at the time while it was pretty bright around the subject area, so maybe that affected the exposure or focus. I wish I had thought of the ship metaphor -- perhaps titling it Bowsprit could have bumped it up a tenth ... Original:  Adjusted:  "Colorized": ', '2004-05-01 14:25:28.000000', NULL, 0),
(692787, 70699, 19780, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by GeneralE:</b></div><hr/><i>I''m a sucker for cloudscapes too, and one reason I went B+W was to put more emphasis on the silhouette aspect rather than make it a nice cloudscape with an antenna in the way.</i></td></tr></table> <br/> <br/>Oh yes, now that I see the color ones, B&amp;W was the right way to go for the challenge. <br/> <br/>But I must say that I love the simple color "adjusted" one. We just don''t get great clouds here in LA like that ... I''d have to go to the high desert for a storm or something.</td>', 'Originally posted by GeneralE:I''m a sucker for cloudscapes too, and one reason I went B+W was to put more emphasis on the silhouette aspect rather than make it a nice cloudscape with an antenna in the way.  Oh yes, now that I see the color ones, B&W was the right way to go for the challenge.  But I must say that I love the simple color "adjusted" one. We just don''t get great clouds here in LA like that ... I''d have to go to the high desert for a storm or something.', '2004-05-01 15:40:48.000000', NULL, 0),
(693184, 70901, 200, '<td valign="top">Ive now looked through all of your entries. You have a special eye. Keep that expression...keep your focus on your inner desire to capture. I like your style. Elaborate and fall within the depth of your own expression...it is good.</td>', 'Ive now looked through all of your entries. You have a special eye. Keep that expression...keep your focus on your inner desire to capture. I like your style. Elaborate and fall within the depth of your own expression...it is good.', '2004-05-01 23:36:33.000000', NULL, 0),
(693558, 70503, 12962, '<td valign="top">Beautiful ... your timing was perfect ... and the golden colors are just out of this world.  It could have done well for the serependity challenge too :-).  Your notes behind the photograph are also illuminating.  New Zealand is such a beautiful country - did postgraduate work in Massey (and have visited Hamilton) and can''t wait to get back ... to photograph again - as there was no consumer digital cameras way back then.</td>', 'Beautiful ... your timing was perfect ... and the golden colors are just out of this world.  It could have done well for the serependity challenge too :-).  Your notes behind the photograph are also illuminating.  New Zealand is such a beautiful country - did postgraduate work in Massey (and have visited Hamilton) and can''t wait to get back ... to photograph again - as there was no consumer digital cameras way back then.', '2004-05-02 12:56:51.000000', NULL, 0),
(693968, 70836, 14986, '<td valign="top">Hello from the critique club!<br/> <br/>One of the first things I do when I look at a critique club photo is to try and guess which challenge it came from before I look at the photo information.  This one really didn''t strike me as a sillhouette.  <br/> <br/>It seems the overall effect is darkness with the one area of light, whereas a sillhouette generally has the opposite I think - an overall effect of light with the one area of darkness.  <br/> <br/>I think the subject itself (the bloom), lacks a really distinctive shape to use to try and capture a sillhouette here.  I think it''s pretty evident that it is some sort of plant, but there''s really nothing to catch my interest.  <br/> <br/>I hope you find this helpful!</td>', 'Hello from the critique club! One of the first things I do when I look at a critique club photo is to try and guess which challenge it came from before I look at the photo information.  This one really didn''t strike me as a sillhouette.   It seems the overall effect is darkness with the one area of light, whereas a sillhouette generally has the opposite I think - an overall effect of light with the one area of darkness.   I think the subject itself (the bloom), lacks a really distinctive shape to use to try and capture a sillhouette here.  I think it''s pretty evident that it is some sort of plant, but there''s really nothing to catch my interest.   I hope you find this helpful!', '2004-05-02 19:24:12.000000', NULL, 0),
(693972, 70566, 14986, '<td valign="top">Hello from the critique club!<br/> <br/>Knew right away (obviously) that this was from the sillhouettes challenge.   That''s always a good sign - definitely meets the challenge.<br/> <br/>I really like the creativity of this shot.  The positioning of the hands and use of the light is perfect I think.  Good use of your filters to even out the lighting to help get the effect you wanted and good editing to get them just right.  I even like the fact that the sky is somewhat featureless here.  A lot of color or clouds in the sky would have detracted, I think, from your main subject.<br/> <br/>I''m not a big fan of this border.  I don''t think it''s too bad, but I also don''t think it really adds anything to the photo.  <br/> <br/>Overall, I think it''s a quality shot which shows creativity and skill at your photography.  Good job!<br/> <br/>I hope you find this critique helpful!</td>', 'Hello from the critique club! Knew right away (obviously) that this was from the sillhouettes challenge.   That''s always a good sign - definitely meets the challenge. I really like the creativity of this shot.  The positioning of the hands and use of the light is perfect I think.  Good use of your filters to even out the lighting to help get the effect you wanted and good editing to get them just right.  I even like the fact that the sky is somewhat featureless here.  A lot of color or clouds in the sky would have detracted, I think, from your main subject. I''m not a big fan of this border.  I don''t think it''s too bad, but I also don''t think it really adds anything to the photo.   Overall, I think it''s a quality shot which shows creativity and skill at your photography.  Good job! I hope you find this critique helpful!', '2004-05-02 19:32:17.000000', NULL, 0),
(693975, 70768, 14986, '<td valign="top">Hello from the Critique Club,<br/> <br/>I''m a sucker for sky shots (sunsets and sunrises) so this one caught my eye right away.  I really like the sky here and that you made use of that colorful backdrop was probably a good idea.<br/> <br/>The subject itself (the boat),is not a strong subject for the sillhouette challenge.  The positioning of the boat as it is loses the top part of the boat into the shoreline.  There''s really not enough light on the water to make the boat stand out very well, but it appears that the boat is slightly out of focus as well.  Or at least, the edges are not very well defined.  <br/> <br/>I wish this could have been captured at a different angle so that the boat was sillhouetted against the sun.  <br/> <br/>Still, not a bad shot at all.  It gives a nice feel to the end of the day and has a relaxing tone to it.  <br/> <br/>I hope you find this critique helpful!</td>', 'Hello from the Critique Club, I''m a sucker for sky shots (sunsets and sunrises) so this one caught my eye right away.  I really like the sky here and that you made use of that colorful backdrop was probably a good idea. The subject itself (the boat),is not a strong subject for the sillhouette challenge.  The positioning of the boat as it is loses the top part of the boat into the shoreline.  There''s really not enough light on the water to make the boat stand out very well, but it appears that the boat is slightly out of focus as well.  Or at least, the edges are not very well defined.   I wish this could have been captured at a different angle so that the boat was sillhouetted against the sun.   Still, not a bad shot at all.  It gives a nice feel to the end of the day and has a relaxing tone to it.   I hope you find this critique helpful!', '2004-05-02 19:39:54.000000', NULL, 0),
(693983, 70887, 14986, '<td valign="top">Hello from the Critique Club!<br/> <br/>I really like the dramatic effect of the colors in your photo.  I even like the border around it.  <br/> <br/>When I think of sillhouette, I don''t think of something like steam, but I think it works okay here.  The inclusion of the trees frames it very nicely.  Your use of neat image helps the colors and the photo.  I think the highlighting of the golden sun around the steam and clouds is what makes this image so strong.  Whatever editing of levels you did worked to bring that out perfectly.<br/> <br/>I don''t recall how this one ended up doing in the challenge, but I like it alot.  Good job!<br/> <br/>I hope you find this critque to be helpful.<br/> <br/></td>', 'Hello from the Critique Club! I really like the dramatic effect of the colors in your photo.  I even like the border around it.   When I think of sillhouette, I don''t think of something like steam, but I think it works okay here.  The inclusion of the trees frames it very nicely.  Your use of neat image helps the colors and the photo.  I think the highlighting of the golden sun around the steam and clouds is what makes this image so strong.  Whatever editing of levels you did worked to bring that out perfectly. I don''t recall how this one ended up doing in the challenge, but I like it alot.  Good job! I hope you find this critque to be helpful. ', '2004-05-02 19:46:27.000000', NULL, 0),
(694126, 70669, 1202, '<td valign="top">dr rick:<br/> <br/>Thank you so very much for the detailed critique of my Cherokee entry.    I dont generally center the main subject but on this one I feel it best that way, due to its shape, at least from the prospective that I used.  I had it turned to face towards and also away from me and it lost its recognizable shape.  This made me think it would gather even less attention than it got. <br/> <br/>I had a lot of fun putting it together, especially when the buzzards kept flying by.  I have several shots with them in different places, but I never got one flying away from the statue, which is what I really would have liked.  Oh by the way my bronze is about 16 inches tall.<br/> <br/>Keep up the good work both on the CC and in the challenges, I always look forward to admiring your work.<br/> <br/>Dick<br/></td>', 'dr rick: Thank you so very much for the detailed critique of my Cherokee entry.    I dont generally center the main subject but on this one I feel it best that way, due to its shape, at least from the prospective that I used.  I had it turned to face towards and also away from me and it lost its recognizable shape.  This made me think it would gather even less attention than it got.  I had a lot of fun putting it together, especially when the buzzards kept flying by.  I have several shots with them in different places, but I never got one flying away from the statue, which is what I really would have liked.  Oh by the way my bronze is about 16 inches tall. Keep up the good work both on the CC and in the challenges, I always look forward to admiring your work. Dick', '2004-05-02 23:26:43.000000', NULL, 0),
(694205, 70503, 8306, '<td valign="top">Great shot! congrats on your first place finish during the challenge.  I like it!</td>', 'Great shot! congrats on your first place finish during the challenge.  I like it!', '2004-05-03 00:17:23.000000', NULL, 0),
